# Add the five chapter divider pages at their planned positions.
# Desired sequence: cover, contents, L1 divider+4 pages, L2 divider+4, L3 divider+5,
# L4 divider+4, L5 divider+4, final review 2 pages.
content_pages = [p for p in PAGES if p['kind'] in ('content','review')]
PAGES = [PAGES[0], PAGES[1]]
pos = 0
for idx, d in enumerate(DIVIDERS):
    PAGES.append({"kind":"divider", **d})
    take = 4 if idx in (0,1,3,4) else 5
    PAGES.extend(content_pages[pos:pos+take])
    pos += take
PAGES.extend(content_pages[pos:])

